DECLARE
  stored "public"."users";
  touched bigint;
  written text[];
  filled record;
  wrote text[] := '{}';
  sent jsonb;
  dflt jsonb;
  exempt boolean := (SELECT _supatype.jwt_role()) = 'service_role';
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM "public"."users" WHERE "id" = OLD."id";
    GET DIAGNOSTICS touched = ROW_COUNT;
    IF touched = 0 THEN
      RETURN NULL;
    END IF;
    RETURN OLD;
  END IF;

  IF TG_OP = 'INSERT' THEN
    FOR filled IN
      SELECT a.attname::text AS col, format_type(a.atttypid, a.atttypmod) AS typ,
             pg_get_expr(d.adbin, d.adrelid) AS expr,
             pg_get_serial_sequence('"public"."users"', a.attname) IS NOT NULL AS drawn
        FROM pg_attribute a
        LEFT JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum
       WHERE a.attrelid = '"public"."users"'::regclass AND a.attname::text IN ('email', 'name', 'id')
    LOOP
      sent := to_jsonb(NEW) -> filled.col;
      dflt := NULL;
      IF filled.expr IS NOT NULL AND NOT filled.drawn
         AND (sent = 'null'::jsonb OR NOT exempt) THEN
        EXECUTE format('SELECT to_jsonb((%s)::%s)', filled.expr, filled.typ) INTO dflt;
      END IF;
      IF sent = 'null'::jsonb THEN
        IF dflt IS NOT NULL THEN
          NEW := jsonb_populate_record(NEW, jsonb_build_object(filled.col, dflt));
        END IF;
      ELSIF dflt IS DISTINCT FROM sent THEN
        wrote := wrote || filled.col;
      END IF;
    END LOOP;
    FOR filled IN
      SELECT a.attname::text AS col, pg_get_serial_sequence('"public"."users"', a.attname) AS seq
        FROM pg_attribute a
       WHERE a.attrelid = '"public"."users"'::regclass AND a.attnum > 0 AND NOT a.attisdropped
         AND pg_get_serial_sequence('"public"."users"', a.attname) IS NOT NULL
    LOOP
      IF to_jsonb(NEW) ->> filled.col IS NULL THEN
        NEW := jsonb_populate_record(NEW, jsonb_build_object(filled.col, nextval(filled.seq)));
      END IF;
    END LOOP;
    written := ARRAY['id', 'email', 'name', 'created_at', 'updated_at']::text[];
    IF NOT exempt AND 'email' = ANY (wrote) AND (SELECT ((SELECT _supatype.jwt_role()) = 'admin') FROM (SELECT NEW.*) AS "users") IS NOT TRUE THEN
      RAISE EXCEPTION 'permission denied for column email of relation users' USING ERRCODE = '42501';
    END IF;
    IF NOT exempt AND 'name' = ANY (wrote) AND (SELECT ((TRUE) AND ((SELECT _supatype.jwt_role()) = 'admin')) FROM (SELECT NEW.*) AS "users") IS NOT TRUE THEN
      RAISE EXCEPTION 'permission denied for column name of relation users' USING ERRCODE = '42501';
    END IF;
    IF NOT exempt AND 'id' = ANY (wrote) AND (SELECT ((SELECT _supatype.jwt_uid()) = "id") FROM (SELECT NEW.*) AS "users") IS NOT TRUE THEN
      RAISE EXCEPTION 'permission denied for column id of relation users' USING ERRCODE = '42501';
    END IF;
    EXECUTE 'INSERT INTO "public"."users" '
      || coalesce('(' || (SELECT string_agg(quote_ident(c), ', ') FROM unnest(written) AS c)
        || ') OVERRIDING SYSTEM VALUE SELECT '
        || (SELECT string_agg('n.' || quote_ident(c), ', ') FROM unnest(written) AS c)
        || ' FROM (SELECT ($1).*) AS n', 'DEFAULT VALUES')
      USING NEW;
    SELECT v.* INTO NEW FROM "api"."users" AS v WHERE v."id" = NEW."id";
    IF NOT FOUND THEN
      RETURN NULL;
    END IF;
    RETURN NEW;
  END IF;

  SELECT * INTO stored FROM "public"."users" WHERE "id" = OLD."id";
  IF NOT exempt THEN
    -- email
    IF (SELECT ((SELECT _supatype.jwt_role()) = 'admin') FROM (SELECT stored.*) AS "users") IS NOT TRUE THEN
      NEW."email" := stored."email";
    ELSIF NEW."email" IS NOT DISTINCT FROM stored."email" THEN
      NEW."email" := stored."email";
    ELSIF TRUE IS NOT TRUE THEN
      RAISE EXCEPTION 'permission denied for column email of relation users' USING ERRCODE = '42501';
    END IF;
    -- name
    IF (SELECT ((SELECT _supatype.jwt_role()) = 'admin') FROM (SELECT stored.*) AS "users") IS NOT TRUE THEN
      NEW."name" := stored."name";
    ELSIF NEW."name" IS NOT DISTINCT FROM stored."name" THEN
      NEW."name" := stored."name";
    ELSIF (SELECT ((TRUE) AND ((SELECT _supatype.jwt_role()) = 'admin')) FROM (SELECT stored.*) AS "users") IS NOT TRUE THEN
      RAISE EXCEPTION 'permission denied for column name of relation users' USING ERRCODE = '42501';
    END IF;
    -- id
    IF TRUE IS NOT TRUE THEN
      NEW."id" := stored."id";
    ELSIF NEW."id" IS NOT DISTINCT FROM stored."id" THEN
      NEW."id" := stored."id";
    ELSIF (SELECT ((SELECT _supatype.jwt_uid()) = "id") FROM (SELECT stored.*) AS "users") IS NOT TRUE THEN
      RAISE EXCEPTION 'permission denied for column id of relation users' USING ERRCODE = '42501';
    END IF;
  END IF;
  UPDATE "public"."users"
     SET "id" = NEW."id",
           "email" = NEW."email",
           "name" = NEW."name",
           "created_at" = NEW."created_at",
           "updated_at" = NEW."updated_at"
   WHERE "id" = OLD."id";
  GET DIAGNOSTICS touched = ROW_COUNT;
  IF touched = 0 THEN
    RETURN NULL;
  END IF;
  SELECT v.* INTO NEW FROM "api"."users" AS v WHERE v."id" = NEW."id";
  IF NOT FOUND THEN
    RETURN NULL;
  END IF;
  RETURN NEW;
END

